-- =====================================================================
--  Pet Biometrics - MySQL database
--  Run in phpMyAdmin (Import / SQL tab) or:  mysql -u root -p < database.sql
-- =====================================================================

CREATE DATABASE IF NOT EXISTS pet_biometrics
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pet_biometrics;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS notifications, lost_reports, adoption_requests, adoption_posts,
                     care_records, pet_images, pets, users;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- 1. users
-- ---------------------------------------------------------------------
CREATE TABLE users (
  user_id       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name          VARCHAR(100)  NOT NULL,
  email         VARCHAR(150)  NOT NULL UNIQUE,
  password_hash VARCHAR(255)  NOT NULL,              -- use PHP password_hash()
  phone         VARCHAR(20)   NULL,
  role          ENUM('user','admin') NOT NULL DEFAULT 'user',
  address       VARCHAR(255)  NULL,
  is_active     TINYINT(1)    NOT NULL DEFAULT 1,   -- 0 = suspended by an admin
  created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_users_role (role)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 2. pets
-- ---------------------------------------------------------------------
CREATE TABLE pets (
  pet_id      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  owner_id    INT UNSIGNED NOT NULL,
  name        VARCHAR(100) NOT NULL,
  species     ENUM('Dog','Cat','Bird','Rabbit','Other') NOT NULL DEFAULT 'Dog',
  breed       VARCHAR(100) NULL,
  age         DECIMAL(4,1) NULL,
  gender      ENUM('Male','Female') NOT NULL DEFAULT 'Male',
  color       VARCHAR(60)  NULL,
  description TEXT         NULL,
  status      ENUM('owned','adoption','lost','adopted') NOT NULL DEFAULT 'owned',
  location    VARCHAR(120) NULL,                      -- used by frontend filters
  photo_ratio DECIMAL(5,3) NULL,                      -- width / height of the cover photo (gallery layout)
  created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_pets_owner FOREIGN KEY (owner_id) REFERENCES users(user_id) ON DELETE CASCADE,
  INDEX idx_pets_status (status),
  INDEX idx_pets_species (species),
  INDEX idx_pets_location (location)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 3. pet_images  (embedding_vector is filled by the Python ML service)
-- ---------------------------------------------------------------------
CREATE TABLE pet_images (
  image_id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  pet_id           INT UNSIGNED NOT NULL,
  image_path       VARCHAR(255) NOT NULL,
  is_primary       TINYINT(1)   NOT NULL DEFAULT 0,
  embedding_vector LONGTEXT     NULL,                 -- JSON array of floats
  uploaded_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_img_pet FOREIGN KEY (pet_id) REFERENCES pets(pet_id) ON DELETE CASCADE,
  INDEX idx_img_pet (pet_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 4. care_records
-- ---------------------------------------------------------------------
CREATE TABLE care_records (
  record_id     INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  pet_id        INT UNSIGNED NOT NULL,
  type          ENUM('Vaccination','Deworming','Vet Checkup','Grooming','Medication','Other') NOT NULL,
  date          DATE NOT NULL,
  notes         TEXT NULL,
  next_due_date DATE NULL,
  CONSTRAINT fk_care_pet FOREIGN KEY (pet_id) REFERENCES pets(pet_id) ON DELETE CASCADE,
  INDEX idx_care_due (next_due_date),
  INDEX idx_care_pet (pet_id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 5. adoption_posts
-- ---------------------------------------------------------------------
CREATE TABLE adoption_posts (
  post_id    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  pet_id     INT UNSIGNED NOT NULL,
  posted_by  INT UNSIGNED NOT NULL,
  location   VARCHAR(120) NOT NULL,
  note       TEXT NULL,
  status     ENUM('pending','active','adopted','rejected') NOT NULL DEFAULT 'active',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_post_pet  FOREIGN KEY (pet_id)    REFERENCES pets(pet_id)   ON DELETE CASCADE,
  CONSTRAINT fk_post_user FOREIGN KEY (posted_by) REFERENCES users(user_id) ON DELETE CASCADE,
  INDEX idx_post_status (status)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 6. adoption_requests
-- ---------------------------------------------------------------------
CREATE TABLE adoption_requests (
  request_id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  post_id      INT UNSIGNED NOT NULL,
  requester_id INT UNSIGNED NOT NULL,
  phone        VARCHAR(20) NULL,
  message      TEXT NOT NULL,
  status       ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  date         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_req_post FOREIGN KEY (post_id)      REFERENCES adoption_posts(post_id) ON DELETE CASCADE,
  CONSTRAINT fk_req_user FOREIGN KEY (requester_id) REFERENCES users(user_id)          ON DELETE CASCADE,
  UNIQUE KEY uq_one_request (post_id, requester_id),
  INDEX idx_req_status (status)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 7. lost_reports  (both "I lost my pet" and "I found a pet" reports)
--    embedding_vector : photo fingerprint from the Python ML service
--    suggestion_json  : best look-alike found automatically when the report arrived
--    matched_pet_id / matched_report_id : the match an ADMIN confirmed
-- ---------------------------------------------------------------------
CREATE TABLE lost_reports (
  report_id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  reporter_id       INT UNSIGNED NOT NULL,
  report_type       ENUM('lost','found') NOT NULL DEFAULT 'found',
  pet_name          VARCHAR(100) NULL,
  pet_id            INT UNSIGNED NULL,                -- registered pet the reporter says is theirs (lost reports)
  image_path        VARCHAR(255) NOT NULL,
  species           ENUM('Dog','Cat','Bird','Rabbit','Other') NOT NULL DEFAULT 'Dog',
  description       TEXT NULL,
  phone             VARCHAR(20) NULL,
  location          VARCHAR(255) NOT NULL,
  found_date        DATE NOT NULL,                    -- date lost / date found
  status            ENUM('open','matched','resolved') NOT NULL DEFAULT 'open',
  admin_note        VARCHAR(500) NULL,
  embedding_vector  LONGTEXT NULL,
  suggestion_json   TEXT NULL,
  matched_pet_id    INT UNSIGNED NULL,
  matched_report_id INT UNSIGNED NULL,
  match_score       DECIMAL(5,2) NULL,                -- 0 - 100
  created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_lost_user   FOREIGN KEY (reporter_id)       REFERENCES users(user_id)          ON DELETE CASCADE,
  CONSTRAINT fk_lost_pet    FOREIGN KEY (matched_pet_id)    REFERENCES pets(pet_id)            ON DELETE SET NULL,
  CONSTRAINT fk_lost_mypet  FOREIGN KEY (pet_id)            REFERENCES pets(pet_id)            ON DELETE SET NULL,
  CONSTRAINT fk_lost_report FOREIGN KEY (matched_report_id) REFERENCES lost_reports(report_id) ON DELETE SET NULL,
  INDEX idx_lost_date (found_date),
  INDEX idx_lost_status (status, report_type)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 8. notifications
-- ---------------------------------------------------------------------
CREATE TABLE notifications (
  notif_id   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id    INT UNSIGNED NOT NULL,
  type       ENUM('match','adoption','care','system','report') NOT NULL DEFAULT 'system',
  message    VARCHAR(500) NOT NULL,
  ref_id     INT UNSIGNED NULL,                      -- report_id for type 'report'
  is_read    TINYINT(1) NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,
  INDEX idx_notif_user_read (user_id, is_read)
) ENGINE=InnoDB;

-- =====================================================================
--  Useful views
-- =====================================================================
CREATE OR REPLACE VIEW v_adoptable_pets AS
SELECT p.*, u.name AS owner_name, u.phone AS owner_phone,
       (SELECT image_path FROM pet_images i WHERE i.pet_id = p.pet_id
         ORDER BY i.is_primary DESC, i.image_id ASC LIMIT 1) AS cover_image
FROM pets p
JOIN users u ON u.user_id = p.owner_id
WHERE p.status = 'adoption';

CREATE OR REPLACE VIEW v_upcoming_care AS
SELECT c.*, p.name AS pet_name, p.owner_id,
       DATEDIFF(c.next_due_date, CURDATE()) AS days_left
FROM care_records c
JOIN pets p ON p.pet_id = c.pet_id
WHERE c.next_due_date IS NOT NULL;

-- =====================================================================
--  Auto-notify owner when a care record is due soon (daily event)
--  Needs:  SET GLOBAL event_scheduler = ON;
-- =====================================================================
DELIMITER $$
CREATE EVENT IF NOT EXISTS ev_care_reminders
ON SCHEDULE EVERY 1 DAY STARTS (CURRENT_DATE + INTERVAL 1 DAY + INTERVAL 8 HOUR)
DO
BEGIN
  INSERT INTO notifications (user_id, type, message)
  SELECT v.owner_id, 'care',
         CONCAT(v.pet_name, '''s ', LOWER(v.type), ' is due in ', v.days_left, ' day(s).')
  FROM v_upcoming_care v
  WHERE v.days_left BETWEEN 0 AND 3
    AND NOT EXISTS (
      SELECT 1 FROM notifications n
      WHERE n.user_id = v.owner_id AND n.type = 'care'
        AND n.message = CONCAT(v.pet_name, '''s ', LOWER(v.type), ' is due in ', v.days_left, ' day(s).')
        AND DATE(n.created_at) = CURDATE()
    );
END$$
DELIMITER ;

